from pptx import Presentation
from pathlib import Path
ppt=Path('/app/output/final_deck.pptx')
prs=Presentation(ppt)
print('slides', len(prs.slides))
print('size', prs.slide_width, prs.slide_height, 'ratio', prs.slide_width/prs.slide_height)
for i, s in enumerate(prs.slides, 1):
    texts=[]; tables=0; bad=[]
    for sh in s.shapes:
        if hasattr(sh,'text') and sh.text.strip():
            texts.append(sh.text.strip().replace('\n',' | ')[:120])
        if getattr(sh,'has_table',False):
            tables+=1
        # check outside slide with small tolerance
        if sh.left < -10000 or sh.top < -10000 or sh.left+sh.width > prs.slide_width+10000 or sh.top+sh.height > prs.slide_height+10000:
            bad.append((sh.name, sh.left, sh.top, sh.width, sh.height))
    print('\nSLIDE', i, 'tables', tables, 'bad_bounds', len(bad))
    for t in texts[:8]: print(' ', t)
    if bad: print(' BAD', bad[:3])
